import os
import json
#import torch
import onnxruntime as ort
from collections.abc import Mapping, Sequence

def load_meta_data(raw: Mapping) -> dict:
    """
    Recursively walk a Mapping, parsing any JSON‐encoded strings
    and turning nested mappings/lists into pure Python structures.
    """
    loaded = {}
    for k, v in raw.items():
        # 1) If it's a JSON string, try to parse it
        if isinstance(v, str):
            try:
                v = json.loads(v)
            except json.JSONDecodeError:
                pass
            loaded[k] = v

        # 2) If it's a mapping, recurse
        elif isinstance(v, Mapping):
            loaded[k] = load_mapping(v)

        # 3) If it's a non‐string sequence, recurse into items
        elif isinstance(v, Sequence):
            new_list = []
            for item in v:
                if isinstance(item, Mapping):
                    new_list.append(load_mapping(item))
                else:
                    new_list.append(item)
            loaded[k] = new_list

        # 4) Anything else, keep as is
        else:
            loaded[k] = v

    return loaded

def recursive_print(d: Mapping, indent: int = 0, verbose: bool = False):
    """
    Recursively prints a mapping:
      • simple values first,
      • then lists (one-per-line, bulleted),
      • then dicts (recurse),
      • each level indented by 2 spaces,
      • visible keys printed first; when verbose, hidden keys (starting with '.') printed last.
    """
    all_keys = list(d.keys())
    # split into visible vs hidden
    visible_keys = [k for k in all_keys if not k.startswith('.')]
    hidden_keys  = [k for k in all_keys if k.startswith('.')] if verbose else []

    # decide print order: visible, then (if verbose) hidden
    key_groups = [visible_keys]
    if verbose:
        key_groups.append(hidden_keys)

    if not any(key_groups):
        return

    # compute padding across all keys we will print
    printed_keys = visible_keys + hidden_keys
    key_width = max(len(k) for k in printed_keys)

    def fmt(k): return f"{k}:".ljust(key_width + 1)

    # process each group in order
    for keys in key_groups:
        if not keys:
            continue

        # classify keys in this group
        simple_keys = []
        list_keys   = []
        dict_keys   = []
        for k in keys:
            v = d[k]
            if isinstance(v, Mapping):
                dict_keys.append(k)
            elif isinstance(v, Sequence) and not isinstance(v, str):
                list_keys.append(k)
            else:
                simple_keys.append(k)

        simple_keys.sort()
        list_keys.sort()
        dict_keys.sort()

        # 1) print simple (non-list, non-dict) values
        for k in simple_keys:
            v = d[k]
            if isinstance(v, str):
                try:
                    parsed = json.loads(v)
                    if not isinstance(parsed, (Mapping, Sequence)):
                        v = parsed
                except json.JSONDecodeError:
                    pass
            print("  " * indent + fmt(k), v)

        # 2) print lists, one item per line
        for k in list_keys:
            v = d[k]
            print("  " * indent + fmt(k))
            for item in v:
                if isinstance(item, Mapping):
                    recursive_print(item, indent + 1, verbose)
                else:
                    print("  " * (indent + 1) + f"- {item}")

        # 3) recurse into dicts
        for k in dict_keys:
            print("  " * indent + fmt(k))
            recursive_print(d[k], indent + 1, verbose)

class OnnxInfer:
    def __init__(self, onnx_model_path, verbose=False, input_name="obs", awd=False):
        # ort.preload_dlls(directory="")
        print(ort.__file__)
        print(ort.get_available_providers())
        providers = ['CUDAExecutionProvider', 'CPUExecutionProvider']
        available = ort.get_available_providers() or []
        if 'CUDAExecutionProvider' not in available:
            providers = ['CPUExecutionProvider']
        self.ort_session = ort.InferenceSession(onnx_model_path, providers=providers)
        self.meta = self.ort_session.get_modelmeta()
        meta_data = self.meta.custom_metadata_map
        self.input_name = self.ort_session.get_inputs()[0].name
        self.awd = awd

        meta = {
            "Model":         os.path.basename(onnx_model_path),
            "Producer name": self.meta.producer_name,
            "Domain":        self.meta.domain,
            "Description":   self.meta.description,
            "Graph name":    self.meta.graph_name,
        }
        meta.update(meta_data)
        info = load_meta_data(meta)
        self.info = info
        config = info['.Config']

        self.KD = info['.KD']
        self.KP = info['.KP']
        self.ctrl_dt = config['ctrl_dt']
        self.vel_scale = config['dof_vel_scale']
        self.action_scale = config['action_scale']
        self.COMMANDS_RANGE_X = config['lin_vel_x']
        self.COMMANDS_RANGE_Y = config['lin_vel_y']
        self.COMMANDS_RANGE_THETA = config['ang_vel_yaw']
        self.walk_in_place_enable = bool(config['walk_in_place_prob'] != 0.0)
        nb_steps_in_period = info['.nb_steps_in_period']
        if nb_steps_in_period is None:
            nb_steps_in_period = meta_data.get('nb_steps_in_period')
            print(f"nb_steps_in_period: {nb_steps_in_period}")
        self.action_offset = info['.ActionOffset']
        self.initial_action_pose = info['.InitialActionPose']
        self.joints = info['.Joints']
        self.commands = info.get('.Commands')
        self.contacts = info.get('.Contacts', False)
        self.quat = info.get('.Quat', True)
        if nb_steps_in_period is None:
            raise ValueError("Expected 'nb_steps_in_period' in meta data")
        try:
            self.nb_steps_in_period = int(nb_steps_in_period)
            print(f"self.nb_steps_in_period: {self.nb_steps_in_period}")
        except ValueError:
            raise ValueError(f"Expected integer metadata for 'nb_steps_in_period', got: {nb_steps_in_period!r}")

        if self.commands == None:
            # Fallback on hardcoded
            self.commands = [
                "lin_vel_x",       # 0
                "lin_vel_y",       # 1
                "ang_vel_yaw",     # 2
                "height",          # 3
                "neck_pitch",      # 4
                "head_pitch",      # 5
                "head_yaw",        # 6
                "head_roll",       # 7
                "trunk_pitch_cmd", # 8
                "trunk_yaw_cmd",   # 9
                "trunk_roll_cmd",  # 10
            ]
        self.command_size = len(self.commands)
        self.command_index = {name: i for i, name in enumerate(self.commands)}

        recursive_print(meta, 0, verbose)

    def get_providers(self):
        return self.ort_session.get_providers()

    def infer(self, inputs):
        if self.awd:
            outputs = self.ort_session.run(None, {self.input_name: [inputs]})
            return outputs[0][0]
        else:
            outputs = self.ort_session.run(
                None, {self.input_name: inputs.astype("float32")}
            )
            return outputs[0]


if __name__ == "__main__":
    import argparse
    import numpy as np
    import time

    parser = argparse.ArgumentParser()
    parser.add_argument("-o", "--onnx_model_path", type=str, required=True)
    args = parser.parse_args()

    oi = OnnxInfer(args.onnx_model_path, awd=True)
    inputs = np.random.uniform(size=54).astype(np.float32)
    inputs = np.arange(47).astype(np.float32)
    times = []
    for i in range(1000):
        start = time.time()
        print(oi.infer(inputs))
        times.append(time.time() - start)

    print("Average time: ", sum(times) / len(times))
    print("Average fps: ", 1 / (sum(times) / len(times)))
